import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        while (first != null && first.trim().isEmpty()) {
            first = br.readLine();
        }
        if (first == null) {
            return;
        }
        String[] mn = first.trim().split("\\s+");
        int m = Integer.parseInt(mn[0]);
        int n = Integer.parseInt(mn[1]);

        char[][] grid = new char[m][];
        for (int i = 0; i < m; i++) {          // 每行一个长度 n 的字符串
            String s = br.readLine();
            while (s != null && s.trim().isEmpty()) {
                s = br.readLine();
            }
            grid[i] = (s == null ? "" : s.trim()).toCharArray();
        }

        boolean[][] seen = new boolean[m][n];
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        int blocks = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != '1' || seen[i][j]) {
                    continue;
                }
                blocks++;
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[]{i, j});
                seen[i][j] = true;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    int x = cur[0], y = cur[1];
                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n        // 先判越界再访问
                                && grid[nx][ny] == '1' && !seen[nx][ny]) {
                            seen[nx][ny] = true;
                            q.add(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
        System.out.println(blocks);
    }
}

