import java.io.*;
import java.util.*;

public class Main {
    static class ListNode {
        int val;
        ListNode next;

        ListNode(int val) {
            this.val = val;
        }
    }

    static ListNode build(int[] vals) {
        ListNode dummy = new ListNode(0);        // 哨兵节点，尾插建表
        ListNode cur = dummy;
        for (int v : vals) {
            cur.next = new ListNode(v);
            cur = cur.next;
        }
        return dummy.next;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        List<Integer> data = new ArrayList<>();
        while (in.nextToken() != StreamTokenizer.TT_EOF) {
            data.add((int) in.nval);
        }
        if (data.isEmpty()) {
            return;
        }
        int p = 0;
        int n = data.get(p++);
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) {
            vals[i] = data.get(p++);
        }
        ListNode head = build(vals);

        ListNode prev = null;                    // 反转链表
        while (head != null) {
            ListNode nxt = head.next;
            head.next = prev;
            prev = head;
            head = nxt;
        }

        StringBuilder sb = new StringBuilder();  // 先攒起来最后一起输出
        while (prev != null) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(prev.val);
            prev = prev.next;
        }
        System.out.println(sb);
    }
}

