import java.io.*;
import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;

        TreeNode(int val) {
            this.val = val;
        }
    }

    static TreeNode build(List<String> tokens) {
        if (tokens.isEmpty() || tokens.get(0).equals("null")) {
            return null;
        }
        TreeNode root = new TreeNode(Integer.parseInt(tokens.get(0)));
        Deque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.size()) {
            TreeNode node = q.poll();
            if (!tokens.get(i).equals("null")) {         // null 不建节点
                node.left = new TreeNode(Integer.parseInt(tokens.get(i)));
                q.add(node.left);
            }
            i++;
            if (i < tokens.size() && !tokens.get(i).equals("null")) {
                node.right = new TreeNode(Integer.parseInt(tokens.get(i)));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static StringBuilder out = new StringBuilder();

    static void dfs(TreeNode node) {                     // 中序
        if (node == null) {
            return;
        }
        dfs(node.left);
        if (out.length() > 0) {
            out.append(' ');
        }
        out.append(node.val);
        dfs(node.right);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            for (String s : line.split("\\s+")) {
                tokens.add(s);
            }
        }
        if (tokens.isEmpty()) {
            return;
        }
        TreeNode root = build(tokens.subList(1, tokens.size()));   // 第一个是 n
        dfs(root);
        System.out.println(out);
    }
}

