import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        List<Long> data = new ArrayList<>();
        while (in.nextToken() != StreamTokenizer.TT_EOF) {
            data.add((long) in.nval);
        }
        if (data.isEmpty()) {
            return;
        }
        int p = 0;
        int n = (int) (long) data.get(p++);
        int m = (int) (long) data.get(p++);
        List<List<long[]>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            g.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            int u = (int) (long) data.get(p++);
            int v = (int) (long) data.get(p++);
            long w = data.get(p++);
            g.get(u).add(new long[]{v, w});       // 边存成 {点, 权重}
            g.get(v).add(new long[]{u, w});
        }

        int s = (int) (long) data.get(p++);
        final long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        dist[s] = 0;
        PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        heap.add(new long[]{0, s});               // 堆里是 (距离, 节点)
        while (!heap.isEmpty()) {
            long[] cur = heap.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d > dist[u]) {                    // 过期状态直接跳过
                continue;
            }
            for (long[] e : g.get(u)) {
                int v = (int) e[0];
                long nd = d + e[1];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    heap.add(new long[]{nd, v});
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) {
                sb.append(' ');
            }
            sb.append(dist[i] == INF ? "inf" : Long.toString(dist[i]));
        }
        System.out.println(sb);
    }
}

