import java.io.*;
import java.util.*;

public class Main {
    static int[] parent;

    static int find(int x) {              // 循环版路径压缩，避免递归过深
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        List<Integer> data = new ArrayList<>();
        while (in.nextToken() != StreamTokenizer.TT_EOF) {
            data.add((int) in.nval);
        }
        if (data.isEmpty()) {
            return;
        }
        int p = 0;
        int n = data.get(p++);
        int m = data.get(p++);
        parent = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
        }

        int merged = 0;
        for (int i = 0; i < m; i++) {      // 边读边合并，不用存图
            int u = data.get(p++), v = data.get(p++);
            int ru = find(u), rv = find(v);
            if (ru != rv) {
                parent[ru] = rv;
                merged++;
            }
        }
        System.out.println(n - merged);    // 连通块个数
    }
}

