    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        List<Integer> data = new ArrayList<>();
        while (in.nextToken() != StreamTokenizer.TT_EOF) {
            data.add((int) in.nval);
        }
        if (data.isEmpty()) {
            return;
        }
        int p = 0;
        int n = data.get(p++);
        int m = data.get(p++);
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            g.add(new ArrayList<>());
        }
        int[] indeg = new int[n + 1];
        for (int i = 0; i < m; i++) {      // 有向图，只加一次边
            int u = data.get(p++), v = data.get(p++);
            g.get(u).add(v);
            indeg[v]++;
        }

        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (indeg[i] == 0) {
                q.add(i);
            }
        }
        StringBuilder sb = new StringBuilder();
        int cnt = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            cnt++;
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(u);
            for (int v : g.get(u)) {
                indeg[v]--;
                if (indeg[v] == 0) {
                    q.add(v);
                }
            }
        }
        System.out.println(cnt == n ? sb.toString() : "-1");   // 出队不足 n 个就是有环
    }
}

