import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken();
        int n = (int) st.nval;
        int[] a = new int[n];
        int sum = 0;
        for (int i = 0; i < n; i++) {
            st.nextToken();
            a[i] = (int) st.nval;
            sum += a[i];
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(a[i]).append(i == n - 1 ? "\n" : " ");
        for (int x : a) sb.append(x).append('\n');
        sb.append(String.format(Locale.US, "%.2f\n", (double) sum / n));

        int[][] rows = {{1, 2}, {3}};
        sb.append(rows.length).append('\n');
        for (int[] r : rows) {
            for (int i = 0; i < r.length; i++) sb.append(r[i]).append(i == r.length - 1 ? "\n" : " ");
        }
        System.out.print(sb);
    }
}
